// Email + mailing domain: email drafts (created in the generator), audiences,
// campaigns and their statistics. MOCK implementation: drafts and user-created
// campaigns persist in localStorage; audiences and baseline campaign stats are
// generated by a seeded PRNG so numbers are stable. The seam for a real ESP
// (SendGrid / Mailgun / etc.) is `sendCampaign` + `getMailOverview`.

export type EmailStyle = "promo" | "newsletter" | "announcement" | "minimal";

export const EMAIL_STYLES: { id: EmailStyle; label: string }[] = [
  { id: "promo", label: "Промо / оффер" },
  { id: "newsletter", label: "Дайджест" },
  { id: "announcement", label: "Анонс" },
  { id: "minimal", label: "Минимал" },
];

export interface EmailDraft {
  id: string;
  name: string;
  subject: string;
  preheader: string;
  brand: string;
  brandMode: "text" | "logo"; // show brand as text name or as an uploaded logo
  style: EmailStyle;
  accent: string; // hex — drives CTA gradient + **highlights**
  dark: boolean; // dark iGaming promo look vs light
  heroImage: string; // data URL (optional hero banner)
  logo: string; // data URL (brand logo)
  logoMode: "reference" | "overlay"; // logo as generation reference or PNG overlay
  heroTitle: string;
  heroSubtitle: string;
  body: string; // supports **bold accent** markers
  steps: string[]; // "how to claim the bonus" steps
  ctaText: string; // primary CTA (e.g. PLAY NOW)
  ctaUrl: string;
  bonusCtaText: string; // secondary CTA (e.g. GET BONUS)
  footer: string;
  unsubscribeUrl: string; // link for the unsubscribe button
  updatedAt: string; // ISO
}

const DRAFTS_KEY = "dw_email_drafts";

